mapper.select:
SELECT g.* FROM script_marketing_group g JOIN script_marketing_task t ON t.id=g.task_id AND t.tenant_id=g.tenant_id
WHERE t.status IN (1,2) AND (g.next_at <= #{now} OR t.end_at <= #{now}
OR (t.account_group_id IS NOT NULL AND EXISTS (
  SELECT 1 FROM script_marketing_send_record r
  WHERE r.tenant_id=g.tenant_id AND r.group_id=g.id AND r.status=1
  AND r.result_deadline_at <= #{now}
)))
ORDER BY g.next_at, g.id LIMIT #{limit}
